43	          full ? "w-full" : "",
44	          VARIANTS[variant],
45	          className,
46	        ]
47	          .filter(Boolean)
48	          .join(" ")}
49	        {...rest}
50	      >
51	        {Icon ? <Icon size={20} strokeWidth={2} aria-hidden="true" /> : null}
52	        {children}
